arguments.command:
python3 -I -c 'import json, pathlib, collections, statistics
r=pathlib.Path("/user/user1/harbor-runs/39325fe6b8b8/workspace/observed_run")
ms=[json.loads(x) for x in (r/"metrics.jsonl").read_text().splitlines()]
print("METRICS",len(ms),"steps",[m["step"] for m in ms])
keys=["val/test_score/openai/gsm8k","critic/score/mean","actor/pg_loss","actor/ppo_kl","actor/pg_clipfrac","actor/entropy_loss","actor/grad_norm","actor/lr_used","response_length/mean","response_length/clip_ratio","critic/kl"]
print("step "+" ".join(keys))
for m in ms: print(str(m["step"])+" "+" ".join(str(m.get(k,"-")) for k in keys))
for fn in ["dataset.jsonl","objective.jsonl","rewards.jsonl","validation.jsonl"]:
 xs=[json.loads(x) for x in (r/fn).read_text().splitlines()]
 print("\n",fn,"records",len(xs),"keys",list(xs[0]),"steps",collections.Counter(x.get("trainer_step") for x in xs))
 if fn=="dataset.jsonl":
  bad=[x for x in xs if x["canonical_answer"]!=x["training_answer"]]
  print("answer mismatches",len(bad),"of",len(xs),"splits",collections.Counter(x["split"] for x in xs),"bad splits",collections.Counter(x["split"] for x in bad)); print("first mismatches",bad[:12])
 if fn=="objective.jsonl":
  print("first",xs[0]); print("last",xs[-1]);
  for s in sorted(set(x["trainer_step"] for x in xs)):
   ys=[x for x in xs if x["trainer_step"]==s]
   print("objstep",s,"n",len(ys),"loss",sum(x["loss"] for x in ys)/len(ys),"behavior_obj",sum(x["behavior_objective"] for x in ys)/len(ys),"repkl",max(abs(x["reported_kl"]) for x in ys),"behkl",sum(x["behavior_kl"] for x in ys)/len(ys),"maxdelta",max(x["logp_delta_max"] for x in ys),"clip",sum(x["clip_fraction"] for x in ys)/len(ys))
 if fn=="rewards.jsonl":
  print("score",sum(x["score"] for x in xs)/len(xs),"canonical exact",sum(x["exact"] for x in xs)/len(xs),"disagree",sum(x["score"]!=x["exact"] for x in xs))
  for s in sorted(set(x["trainer_step"] for x in xs)):
   ys=[x for x in xs if x["trainer_step"]==s]; print("rewstep",s,"n",len(ys),"score",sum(x["score"] for x in ys)/len(ys),"exact",sum(x["exact"] for x in ys)/len(ys),"disagree",sum(x["score"]!=x["exact"] for x in ys))
 if fn=="validation.jsonl":
  for s in sorted(set(x["trainer_step"] for x in xs)):
   ys=[x for x in xs if x["trainer_step"]==s]; print("valstep",s,"n",len(ys),"score",sum(x["score"] for x in ys)/len(ys),"unique idx",len(set(x["index"] for x in ys)))'

